def transform(g):
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    H,W=len(g),len(g[0])
    def comps():
        seen=set(); res=[]
        for i in range(H):
            for j in range(W):
                if g[i][j]!=bg and (i,j) not in seen:
                    st=[(i,j)]; seen.add((i,j)); comp=[]
                    while st:
                        r,c=st.pop(); comp.append((r,c))
                        for dr in(-1,0,1):
                            for dc in(-1,0,1):
                                a,b=r+dr,c+dc
                                if 0<=a<H and 0<=b<W and g[a][b]!=bg and (a,b) not in seen:
                                    seen.add((a,b)); st.append((a,b))
                    res.append(comp)
        return res
    cs=comps(); obj=max(cs,key=len)
    def nb(cell): return sum(1 for x in obj if abs(x[0]-cell[0])+abs(x[1]-cell[1])==1)
    anchor=max(obj,key=nb)
    pat={(r-anchor[0],c-anchor[1]):g[r][c] for r,c in obj}
    noise=[c for comp in cs if comp!=obj for c in comp]
    res=[row[:] for row in g]
    for (r,c) in noise:
        best=0
        for sh in range(W):
            for s in((sh,) if sh==0 else (sh,-sh)):
                if all(0<=c+dc+s<W for _,dc in pat): best=s; break
            else: continue
            break
        for (dr,dc),v in pat.items(): res[r+dr][c+dc+best]=v
    return res
